{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "additionalProperties": false,
  "required": ["version", "targets", "groups", "dependencies"],
  "properties": {
    "version": { "const": 2 },
    "dependencies": {
      "const": {
        "async": { "package": "semio-framework-async", "features": ["entrypoint"], "devOnly": true },
        "viewport": { "package": "semio-framework-ui-viewport", "devOnly": true }
      }
    },
    "targets": {
      "const": [
        { "name": "test", "features": ["tui-terminal", "wgpu"] },
        { "name": "test-wgpu-engine", "features": ["wgpu-engine"] }
      ]
    },
    "groups": {
      "type": "array",
      "minItems": 3,
      "maxItems": 3,
      "items": { "$ref": "#/$defs/group" }
    }
  },
  "$defs": {
    "source": { "type": "string", "pattern": "^(?![./])[^\\\\]+\\.rs$" },
    "name": { "type": "string", "pattern": "^[a-z][a-z0-9_]*$" },
    "sha256": { "type": "string", "pattern": "^[a-f0-9]{64}$" },
    "law": {
      "type": "object",
      "additionalProperties": false,
      "required": ["name", "sha256", "owner"],
      "properties": {
        "name": { "$ref": "#/$defs/name" },
        "sha256": { "$ref": "#/$defs/sha256" },
        "owner": { "enum": ["portable", "engine"] }
      }
    },
    "helper": {
      "type": "object",
      "additionalProperties": false,
      "required": ["name", "source", "sha256"],
      "properties": {
        "name": { "$ref": "#/$defs/name" },
        "source": { "$ref": "#/$defs/source" },
        "sha256": { "$ref": "#/$defs/sha256" }
      }
    },
    "group": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "portableSource", "engineSource", "productionSource", "laws", "helpers", "sharedDeclarations"],
      "properties": {
        "id": { "enum": ["input", "prepared", "theme"] },
        "portableSource": { "$ref": "#/$defs/source" },
        "engineSource": { "$ref": "#/$defs/source" },
        "productionSource": { "$ref": "#/$defs/source" },
        "laws": { "type": "array", "minItems": 1, "uniqueItems": true, "items": { "$ref": "#/$defs/law" } },
        "helpers": { "type": "array", "uniqueItems": true, "items": { "$ref": "#/$defs/helper" } },
        "sharedDeclarations": { "type": "array", "uniqueItems": true, "items": { "type": "string", "minLength": 1 } }
      }
    }
  }
}

import {test,expect} from "bun:test";
import {readFileSync,existsSync} from "node:fs";
import {resolve} from "node:path";
import {Database} from "bun:sqlite";
import Ajv from "ajv";
import {Reader,Writer} from "protobufjs/minimal.js";
import {applyPatch} from "fast-json-patch";

test("retained inline symbols preserve original wire indices and independent canonical UTF8",()=>{
  const owner=resolve(import.meta.dir,"..");
  const law=JSON.parse(readFileSync(resolve(owner,"🧫️fixtures/🔣️.json"),"utf8"));
  expect(new Ajv({strict:true}).compile(JSON.parse(readFileSync(resolve(owner,"🧬️schema/🔣️.json"),"utf8")))(law)).toBe(true);
  const database=new Database(":memory:");
  try{
    database.exec("CREATE TABLE symbols (ordinal INTEGER PRIMARY KEY, value BLOB NOT NULL)");
    for(const row of law.valid){
      const bytes=Uint8Array.from(Buffer.from(row.hex,"hex"));
      const reader=Reader.create(bytes);
      reader.pos=row.sourceOffset;
      const count=Number(reader.uint64().toString());
      const writer=Writer.create().uint64(count);
      const symbols=[];
      database.exec("DELETE FROM symbols");
      for(let index=0;index<count;index++){
        const raw=reader.bytes();
        writer.bytes(raw);
        symbols.push(new TextDecoder("utf-8",{fatal:true}).decode(raw));
        database.query("INSERT INTO symbols VALUES (?,?)").run(index,raw);
      }
      expect(symbols).toEqual(row.symbols);
      expect(reader.pos).toBe(row.prefixBytes);
      expect(Buffer.from(writer.finish())).toEqual(Buffer.from(bytes.subarray(row.sourceOffset,reader.pos)));
      expect(database.query("SELECT ordinal,value FROM symbols ORDER BY ordinal").all().map((value:any)=>({ordinal:value.ordinal,text:new TextDecoder().decode(value.value)}))).toEqual(row.symbols.map((text:string,ordinal:number)=>({ordinal,text})));
      expect(applyPatch({symbols},[{op:"move",from:"/symbols",path:"/retained"}],true,false).newDocument).toEqual({retained:row.symbols});
    }
    for(const row of law.invalid){
      const bytes=Uint8Array.from(Buffer.from(row.hex,"hex"));
      const reader=Reader.create(bytes);
      if(row.refusal==="symbol-count")expect(Number(reader.uint64().toString())).toBeGreaterThan(law.maximumSymbols);
      else if(row.refusal==="symbol-length"){reader.uint64();expect(Number(reader.uint64().toString())).toBeGreaterThan(law.maximumSymbolBytes);}
      else if(row.refusal==="noncanonical"){
        const count=reader.uint64();const writer=Writer.create().uint64(count);
        if(Number(count.toString())!==0)writer.uint64(reader.uint64());
        expect(Buffer.from(writer.finish())).not.toEqual(Buffer.from(bytes.subarray(0,reader.pos)));
      }else expect(()=>{const count=Number(reader.uint64().toString());for(let index=0;index<count;index++)new TextDecoder("utf-8",{fatal:true}).decode(reader.bytes());}).toThrow();
    }
    const large=law.large.word.repeat(law.large.repetitions);
    const largeBytes=new TextEncoder().encode(large);
    expect(largeBytes.length).toBe(law.large.bytes);
    const largeReader=Reader.create(Writer.create().uint64(1).bytes(largeBytes).finish());
    expect(largeReader.uint64().toString()).toBe("1");
    expect(new TextDecoder("utf-8",{fatal:true}).decode(largeReader.bytes())).toBe(large);
    const emptyWriter=Writer.create().uint64(law.large.emptySymbols);
    for(let index=0;index<law.large.emptySymbols;index++)emptyWriter.bytes(new Uint8Array());
    const emptyReader=Reader.create(emptyWriter.finish());
    expect(emptyReader.uint64().toString()).toBe(String(law.large.emptySymbols));
    for(let index=0;index<law.large.emptySymbols;index++)expect(emptyReader.bytes().length).toBe(0);
    expect(emptyReader.pos).toBe(emptyReader.len);
  }finally{database.close();}
  expect(existsSync(resolve(owner,"🦀️.rs"))).toBe(true);
  const source=readFileSync(resolve(owner,"🦀️.rs"),"utf8");
  expect(source.includes("PagedList<SymbolSpan")).toBe(true);
  expect(source.includes("RetainedCloneBinding::close_one")).toBe(true);
  expect(source.includes("decode_inline_symbols(")).toBe(false);
  expect(source.includes("Utf8Admission")).toBe(false);
  console.log("[DEBUG] Retained inline symbol indices/canonical unsigned wire/UTF8/NUL/empty/duplicate/prefix tail agree with Protobuf.js, fatal TextDecoder, SQLite ordinal BLOBs and RFC6902; native bounded parsing/heap/alias proof remains required");
});

import { expect, test } from "bun:test";
import { existsSync, mkdtempSync, readFileSync, writeFileSync, rmSync } from "node:fs";
import { resolve } from "node:path";

const fixture = JSON.parse(readFileSync(resolve(import.meta.dir, "../🧫️fixtures/🔣️.json"), "utf8"));

test("terminates a bounded owned descendant process", async () => {
  const owner = resolve(import.meta.dir, "../🟦️.ts");
  expect(existsSync(owner)).toBe(true);
  if (!existsSync(owner)) return;
  const artifactParent = process.env.SEMIO_TEST_ARTIFACT_DIR;
  expect(artifactParent).toBeTruthy();
  if (!artifactParent) return;
  const root = mkdtempSync(resolve(artifactParent, "owned-execution-"));
  const marker = resolve(root, "descendant.txt");
  const source = [
    "const {spawn}=require('node:child_process')",
    "const {writeFileSync}=require('node:fs')",
    "const child=spawn(process.execPath,['-e','setTimeout(() => {}, 10000)'],{stdio:'ignore'})",
    `writeFileSync(${JSON.stringify(marker)},String(child.pid))`,
    "setTimeout(() => {}, 10000)",
  ].join(";");
  const { runOwnedCommand } = await import(owner);
  try {
    await expect(runOwnedCommand(process.execPath, ["-e", source], root, "owned-descendant", 2_000, { stdout: "ignore" })).rejects.toThrow(/timeout 2000ms/);
    const descendant = Number(readFileSync(marker, "utf8"));
    const alive = (): boolean => {
      try {
        process.kill(descendant, 0);
        return true;
      } catch {
        return false;
      }
    };
    for (let attempt = 0; attempt < 40 && alive(); attempt++) await Bun.sleep(25);
    try {
      expect(alive()).toBe(false);
    } finally {
      if (alive()) process.kill(descendant, "SIGKILL");
    }
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
}, { timeout: 10_000 });

test("owned command cancellation and UTF-8 reports match independent Node execution", async () => {
  const owner = resolve(import.meta.dir, "../🟦️.ts"), artifactParent = process.env.SEMIO_TEST_ARTIFACT_DIR!;
  expect(artifactParent).toBeTruthy();
  const root = mkdtempSync(resolve(artifactParent, "owned-reports-")), module = resolve(root, "owner.mjs");
  const { createRequire } = await import("node:module"), { spawnSync } = await import("node:child_process");
  const bundled = await createRequire(import.meta.url)("esbuild").build({entryPoints:[owner],bundle:true,write:false,platform:"node",format:"esm",metafile:true,logLevel:"silent"});
  expect(Object.keys(bundled.metafile.inputs).every((path:string)=>path.startsWith("🧰️framework/🔨️modules/🏃️process/"))).toBe(true);
  writeFileSync(module, bundled.outputFiles[0].text);
  const run = async (api: any, executable: string, row: any): Promise<any> => {
    const marker = resolve(root, row.mode + ".txt"), controller = new AbortController(), lines: string[] = [];
    const source = row.mode === "lines" ? "const b=Buffer.from('first 🧪\\nlast');process.stdout.write(b.subarray(0,8));setTimeout(()=>process.stdout.write(b.subarray(8)),10)" : row.mode === "pre-abort" ? `require('node:fs').writeFileSync(${JSON.stringify(marker)},'spawned')` : row.mode === "abort" ? "console.log('ready');setTimeout(()=>{},10000)" : "process.exit(7)";
    if (row.mode === "pre-abort") controller.abort();
    let error: string | null = null;
    try { await api.runOwnedCommand(executable,["-e",source],root,"owned-vector",fixture.reportExecutionBudgetMs,{signal:controller.signal,onLine:(line:string)=>{lines.push(line);if(row.mode === "abort")controller.abort();}}); }
    catch (failure) { error = String(failure); }
    return {lines,error:row.expectedError === null ? error : error?.includes(row.expectedError) ? row.expectedError : error,created:existsSync(marker)};
  };
  const api = await import(owner);
  for (const row of fixture.cases) {
    const expected = {lines:row.expectedLines,error:row.expectedError,created:false};
    expect(await run(api,process.execPath,row)).toEqual(expected);
    const runner = `const fs=require('node:fs');const root=process.argv[2];const row=JSON.parse(fs.readFileSync(0,'utf8'));const existsSync=fs.existsSync;const resolve=require('node:path').resolve;const fixture=${JSON.stringify({reportExecutionBudgetMs:fixture.reportExecutionBudgetMs})};const run=${run.toString()};import(require('node:url').pathToFileURL(process.argv[1]).href).then(api=>run(api,process.execPath,row)).then(value=>console.log('RESULT '+JSON.stringify(value)));`;
    const independent = spawnSync("node",["-e",runner,module,root],{input:JSON.stringify(row),encoding:"utf8",timeout:fixture.reportExecutionBudgetMs+5_000});
    writeFileSync(resolve(root, row.mode + ".log"), independent.stdout + independent.stderr);
    expect(independent.status).toBe(0);
    const result = independent.stdout.match(/RESULT (\{[^\n]+\})/u);
    expect(JSON.parse(result![1])).toEqual(expected);
  }
}, 60_000);


test("progress remains observable until explicitly stopped", async () => {
  const { startNativeProgress } = await import("../🟦️.ts");
  const lines: string[] = [], stop = startNativeProgress(fixture.progress.label, fixture.progress.intervalMs, line => lines.push(line));
  await Bun.sleep(fixture.progress.intervalMs * 4); stop();
  expect(lines.some(line => new RegExp(fixture.progress.pattern).test(line))).toBe(true);
  const count=lines.length;await Bun.sleep(fixture.progress.intervalMs*4);expect(lines.length).toBe(count);
});


test("owned timeout and stop drain descendant-created groups and inherited pipes", async () => {
  const { spawn, spawnSync } = await import("node:child_process"), { default: treeKill } = await import("tree-kill"), { default: Ajv } = await import("ajv/dist/2020.js");
  const corpus = JSON.parse(readFileSync(resolve(import.meta.dir, "../🧫️fixtures/🌳️ownership/🔣️.json"), "utf8"));
  const schema = JSON.parse(readFileSync(resolve(import.meta.dir, "../🧬️schema/🌳️ownership/🔣️.json"), "utf8"));
  expect(new Ajv({ strict: true }).validate(schema, corpus)).toBe(true);
  const { runOwnedCommand } = await import("../🟦️.ts");
  const root = mkdtempSync(resolve(process.env.SEMIO_TEST_ARTIFACT_DIR!, "owned-groups-"));
  const alive = (pid: number): boolean => {
    try { process.kill(pid, 0); } catch { return false; }
    if (process.platform === "win32") return true;
    const state = spawnSync("ps", ["-o", "stat=", "-p", String(pid)], { encoding: "utf8" });
    return state.status === 0 && !state.stdout.trim().startsWith("Z");
  };
  const source = "const {spawn}=require('node:child_process');const child=spawn(process.execPath,['-e','setInterval(()=>{},10000)'],{detached:process.platform!=='win32',stdio:'inherit'});console.log('READY '+JSON.stringify({root:process.pid,descendant:child.pid}));setInterval(()=>{},10000)";
  const unrelated = spawn("node", ["-e", "setInterval(()=>{},10000)"], { stdio: "ignore" });
  const unrelatedExited = new Promise<void>(accept => unrelated.once("exit", () => accept()));
  try {
    for (const row of corpus.cases) {
      for (const implementation of ["tree-kill", "owned"] as const) {
        let pids: number[] = [], settled = false, failure = "", oracle: ReturnType<typeof spawn> | undefined, work: Promise<void> | undefined;
        const controller = new AbortController();
        const ready = (line: string): void => {
          if (!line.startsWith("READY ")) return;
          const value = JSON.parse(line.slice(6)); pids = [value.root, value.descendant];
          if (process.platform !== "win32") {
            const groups = spawnSync("ps", ["-o", "pgid=", "-p", pids.join(",")], { encoding: "utf8" }).stdout.trim().split(/\s+/).map(Number);
            expect(new Set(groups).size).toBe(2);
          }
          if (implementation === "tree-kill") setTimeout(() => treeKill(value.root, "SIGKILL"), row.mode === "timeout" ? row.timeoutMs : 0);
          else if (row.mode === "abort") controller.abort();
          else if (row.mode === "stop") process.emit("SIGTERM");
        };
        try {
          if (implementation === "owned") {
            work = runOwnedCommand("node", ["-e", source], root, "owned-groups", row.timeoutMs, { signal: controller.signal, onLine: ready }).catch(error => { failure = String(error); }).finally(() => { settled = true; });
          } else {
            oracle = spawn("node", ["-e", source], { detached: process.platform !== "win32", stdio: ["ignore", "pipe", "pipe"] });
            oracle.stdout!.on("data", bytes => String(bytes).trim().split("\n").forEach(ready));
            work = new Promise<void>(accept => oracle!.once("close", () => { settled = true; failure = row.expected.reason; accept(); }));
          }
          await Promise.race([work, Bun.sleep(row.settleMs)]);
          for (let attempt = 0; attempt < 20 && pids.some(alive); attempt++) await Bun.sleep(25);
          const result = { settled, survivors: pids.filter(alive).length, unrelatedAlive: alive(unrelated.pid!), reason: failure.includes(row.expected.reason) ? row.expected.reason : failure };
          console.log(`[DEBUG] owned groups implementation=${implementation} mode=${row.mode} result=${JSON.stringify(result)}`);
          expect(pids.length).toBe(2);
          expect(result).toEqual(row.expected);
        } finally {
          for (const pid of [...pids].reverse()) if (alive(pid)) process.kill(pid, "SIGKILL");
          if (oracle?.exitCode === null && oracle.signalCode === null) oracle.kill("SIGKILL");
          if (work) await Promise.race([work, Bun.sleep(1000)]);
        }
      }
    }
  } finally {
    unrelated.kill("SIGKILL"); await unrelatedExited; rmSync(root, { recursive: true, force: true });
  }
}, 60_000);

import {Database} from "bun:sqlite";
import {test, expect} from "bun:test";
import {readFileSync} from "node:fs";
import {resolve, join} from "node:path";
import {applyPatch} from "fast-json-patch";
import {createHash} from "node:crypto";
import {semioSchemaAjvV1} from "../../../../../../../../../../🧰️framework/🔨️modules/🧬️schema/🔮️oracles/✅️validator/🟦️.ts";

test("Drawing initializer closes the original catalog one exactly admitted page at a time",()=>{
  const owner=resolve(import.meta.dir,"../..");
  const directory=join(owner,"🏗️initialization/📚️catalog");
  const law=JSON.parse(readFileSync(join(directory,"🧫️fixtures/🔣️.json"),"utf8"));
  const database=new Database(":memory:");
  try{
    database.exec("CREATE TABLE pages (ordinal INTEGER PRIMARY KEY, lane TEXT UNIQUE NOT NULL, bytes INTEGER NOT NULL)");
    law.lanes.forEach((lane:string,index:number)=>database.query("INSERT INTO pages VALUES (?,?,?)").run(index,lane,128+index));
    let state={pages:law.lanes.map((lane:string,index:number)=>({lane,bytes:128+index}))};
    for(const lane of law.lanes){
      const row=database.query("SELECT ordinal,lane,bytes FROM pages ORDER BY ordinal LIMIT 1").get() as {ordinal:number,lane:string,bytes:number};
      expect(row.lane).toBe(lane);
      for(const grant of [0,row.bytes-1])expect(database.query("SELECT CASE WHEN ? >= bytes THEN bytes ELSE 0 END AS released FROM pages WHERE ordinal=?").get(grant,row.ordinal)).toEqual({released:0});
      expect(database.query("SELECT CASE WHEN ? >= bytes THEN bytes ELSE 0 END AS released FROM pages WHERE ordinal=?").get(row.bytes,row.ordinal)).toEqual({released:row.bytes});
      database.query("DELETE FROM pages WHERE ordinal=?").run(row.ordinal);
      state=applyPatch(state,[{op:"remove",path:"/pages/0"}],true,false).newDocument;
      expect(state.pages.map((page:any)=>page.lane)).toEqual(database.query("SELECT lane FROM pages ORDER BY ordinal").all().map((page:any)=>page.lane));
    }
    expect(state).toEqual({pages:[]});
  }finally{database.close();}
  const host=readFileSync(join(owner,"🦀️.rs"),"utf8");
  const initializer=host.slice(host.indexOf("struct DrawingStoreInitializationAuthority"),host.indexOf("pub fn drawing_document_store_initialization_job"));
  expect(initializer.includes("drop(self.owner_catalog.take())")).toBe(false);
  expect(initializer.includes("close_initialization_catalog(&mut self.owner_catalog, 1, maximum_bytes)")).toBe(true);
  expect(initializer.includes("close_initialization_catalog(&mut self.owner_catalog, maximum_items, maximum_bytes)")).toBe(true);
  expect(initializer.includes("PluginCloseStep::Pending { released_items, released_bytes }")).toBe(true);
  const source=readFileSync(join(directory,"🦀️.rs"),"utf8");
  expect(source.includes("catalog.close_step(1, maximum_bytes)")).toBe(true);
  expect(source.includes("if !catalog.terminal_is_empty()")).toBe(true);
  console.log("[DEBUG] Drawing initializer catalog SQLite exact first-page admission and RFC6902 resident-page order agree; original catalog birth is cold and uncredited");
});

test("Drawing initializer transfers original active owners into inline typed retirement",()=>{
  const owner=resolve(import.meta.dir,"../..");
  const law=JSON.parse(readFileSync(join(owner,"♻️retirement/🧫️fixtures/🔣️.json"),"utf8"));
