  const prefix=Buffer.alloc(11);prefix[0]=0xd8;prefix.writeUInt16BE(law.textDigest.tag,1);prefix.writeBigUInt64BE(BigInt(bytes.length),3);
  const whole=createHash("sha256").update(prefix).update(bytes).digest("hex");
